test('successful application write followed by failed durable outcome append is uncertain and not retryable',async()=>{const h=harness();await runM74Journey(input(),h.deps);h.schema=17;h.outcomeAppendFailure=true;const run=await runM74Journey(input('exercise'),h.deps);expect(run.status).toBe('failed');expect(h.corporate.versions).toHaveLength(2);expect(h.appPosts).toBe(1);expect(readM74Journal(h.journal,company).some(e=>e.kind==='post_intent')).toBe(true);const calls=h.calls.length;expect((await runM74Journey(input('exercise'),h.deps)).stage).toBe('resume_preconditions');expect(h.calls).toHaveLength(calls)})

test('prior gas version or exact-download mutation refuses baseline with zero application writes',async()=>{for(const kind of ['version','download']){const h=harness();if(kind==='version')h.tamperGas=true;else h.tamperDownload=true;const result=await runM74Journey(input(),h.deps);expect(result.status).toBe('failed');expect(h.appPosts).toBe(0);expect(result.allCreatedAuthSessionsClosed).toBe(true);expect(h.logoutCount).toBe(h.tokenCount)}})

test('unknown sign-in and interrupted-attempt journals fail closed without exposing error content',async()=>{const h=harness();h.authFault=true;const unknown=await runM74Journey(input(),h.deps);expect(unknown.status).toBe('failed');expect(unknown.allCreatedAuthSessionsClosed).toBe(false);expect(h.journal).not.toContain('UNEXPECTED_PRIVATE');const n=h.calls.length;await runM74Journey(input('exercise'),h.deps);expect(h.calls).toHaveLength(n);const interrupted=harness();await runM74Journey(input(),interrupted.deps);interrupted.journal=interrupted.journal!.trimEnd().split('\n').slice(0,-1).join('\n')+'\n';const count=interrupted.calls.length;expect((await runM74Journey(input('exercise'),interrupted.deps)).stage).toBe('resume_preconditions');expect(interrupted.calls).toHaveLength(count)})

test('legacy adapter cannot introduce application writes and route guard rejects unrelated tenants/actions',async()=>{const h=harness();h.legacyFault=true;expect((await runM74Journey(input(),h.deps)).status).toBe('failed');expect(h.appPosts).toBe(0);for(const [u,m] of [[HOST+'/workspace-api/workspace/'+id(99)+'/mobile-diesel','GET'],[root+'/mobile-diesel','DELETE'],[root+'/stationary-natural-gas','POST'],[AUTH+'/auth/v1/token?grant_type=refresh_token','POST'],[HOST+'/ready?profile=other','GET'],[HOST+'/ready#override','GET']])expect(()=>validateM74JourneyRoute(u!,m!,company)).toThrow()})
